  S.seedUsed = P.seed;
  let z=(P.seed*2654435761 ^ 0x9e3779b9)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.px=S.rnd()*2-1; S.py=S.rnd()*2-1; S.cc=S.rnd(); S.lastV=-1; S.phase=S.rnd();
