// --- temporal drift (K.t seconds — continuous, never re-phases) ---
const intn=(K.intensity!=null?K.intensity:.6);
const rot=K.t*(0.045+P.speed*0.03) + Math.sin(K.t*0.11)*0.15 + A.lowmid*0.2;
