const FIT=0.9;
const asp=cw>=ch ? ch/cw : cw/ch;
const axf=cw>=ch ? Math.pow(asp,0.4) : 1;
const ayf=cw>=ch ? 1 : Math.pow(asp,0.4);

// --- rolling decay + running max (pass 1) ---
const decay=0.86+P.persist*0.12;
const hist=S.hist, vsum=S.vsum;
let nMax=0;
for (let i=0;i<N4;i++){ const v=hist[i]*decay; hist[i]=v; vsum[i]*=decay; if(v>nMax)nMax=v; }

// --- chaos game (pure-JS; ~25-46k iters, never touches p5) ---
const iters=Math.floor(((10000+P.density*30000)*(0.65+intn*0.5)+A.bass*4000)*(LA*LA)/40000);
let x=S.px, y=S.py, cc=S.cc, lastV=S.lastV;
for (let it=0; it<iters; it++){
  let j=(rnd()*nV)|0; if (j>=nV) j=nV-1;
  if (restrict && j===lastV){ j=(j+1+((rnd()*(nV-1))|0))%nV; }
  lastV=j;
  x = x + (vx[j]-x)*ratio;
  y = y + (vy[j]-y)*ratio;
