  if (ix>=0&&ix<cw&&iy>=0&&iy<ch){ const bi=iy*cw+ix; const nv=hist[bi]+1; hist[bi]=nv; vsum[bi]+=cc; if(nv>nMax)nMax=nv; }
}
S.px=x; S.py=y; S.cc=cc; S.lastV=lastV;

// --- log-density + gamma tone map -> coarse buffer (pass 2) ---
const expo=0.5+P.energy*2.2+K.pulse*0.22+A.rms*1.1;
const invG=1/Math.max(0.3,P.gamma);
const logMax=Math.log(1+nMax*expo)+1e-3;
const st=P.style, ink=(st==='ink');
