else if (st==='ember'){ bgR=16; bgG=6; bgB=4; }
else if (st==='ice'){ bgR=4; bgG=9; bgB=22; }
else if (st==='gold'){ bgR=14; bgG=9; bgB=3; }
else { bgR=9; bgG=7; bgB=22; }
